<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Computer Languages Quiz</title>
  <link rel="stylesheet" href="style.css">
</head>
<body>
  <div id="root"></div>

  <script>
    // React-style component structure
    const Quiz = {
      questions: [
        {
          id: 'q1',
          title: 'Which of these languages are dynamically typed?',
          helpText: 'Dynamically typed languages check types at runtime rather than compile time.',
          options: [
            { id: 'opt1', label: 'Python', correct: true },
            { id: 'opt2', label: 'Java', correct: false },
            { id: 'opt3', label: 'JavaScript', correct: true },
            { id: 'opt4', label: 'C++', correct: false }
          ]
        },
        {
          id: 'q2',
          title: 'Which languages support functional programming paradigms?',
          helpText: null,
          options: [
            { id: 'opt1', label: 'Haskell', correct: true },
            { id: 'opt2', label: 'Lisp', correct: true },
            { id: 'opt3', label: 'Java', correct: false },
            { id: 'opt4', label: 'Rust', correct: true }
          ]
        },
        {
          id: 'q3',
          title: 'Which of these are compiled languages?',
          helpText: null,
          options: [
            { id: 'opt1', label: 'Go', correct: true },
            { id: 'opt2', label: 'C', correct: true },
            { id: 'opt3', label: 'Python', correct: false },
            { id: 'opt4', label: 'Rust', correct: true }
          ]
        }
      ],

      renderQuestion(question) {
        const helpTextHtml = question.helpText 
          ? `<div class="help-text">${question.helpText}</div>` 
          : '';

        const optionsHtml = question.options
          .map(option => `
            <div class="option">
              <input 
                type="checkbox" 
                id="${question.id}_${option.id}" 
                name="${question.id}"
                value="${option.id}"
                data-correct="${option.correct}"
              />
              <label for="${question.id}_${option.id}">${option.label}</label>
            </div>
          `)
          .join('');

        return `
          <div class="form-field">
            <h2>${question.title}</h2>
            ${helpTextHtml}
            <div class="options">
              ${optionsHtml}
            </div>
          </div>
        `;
      },

      render() {
        const questionsHtml = this.questions
          .map(q => this.renderQuestion(q))
          .join('');

        return `
          <div class="quiz-container">
            <header class="quiz-header">
              <h1>💻 Computer Languages Quiz</h1>
              <p>Test your knowledge about programming languages. Select all correct answers for each question.</p>
            </header>

            <form id="quiz-form">
              ${questionsHtml}

              <div class="form-actions">
                <button type="submit" class="btn-submit">Submit Quiz</button>
              </div>
            </form>

            <div id="results" class="results-container" style="display: none;">
              <div class="results-content">
                <h2>Quiz Results</h2>
                <div id="results-details"></div>
                <button type="button" class="btn-retry" onclick="location.reload()">Try Again</button>
              </div>
            </div>
          </div>
        `;
      }
    };

    // Initialize the app
    document.addEventListener('DOMContentLoaded', () => {
      const root = document.getElementById('root');
      root.innerHTML = Quiz.render();

      const form = document.getElementById('quiz-form');
      form.addEventListener('submit', (e) => {
        e.preventDefault();
        evaluateQuiz();
      });
    });

    function evaluateQuiz() {
      let score = 0;
      let totalQuestions = Quiz.questions.length;
      const results = [];

      Quiz.questions.forEach(question => {
        const selectedCheckboxes = document.querySelectorAll(
          `input[name="${question.id}"]:checked`
        );
        const correctOptions = question.options.filter(opt => opt.correct);

        const selected = Array.from(selectedCheckboxes).map(cb => cb.value);
        const correctIds = correctOptions.map(opt => opt.id);

        const isCorrect = 
          selected.length === correctIds.length &&
          selected.every(id => correctIds.includes(id));

        if (isCorrect) score++;

        results.push({
          question: question.title,
          isCorrect,
          selected: selected.map(id => 
            question.options.find(opt => opt.id === id).label
          ),
          correct: correctOptions.map(opt => opt.label)
        });
      });

      displayResults(score, totalQuestions, results);
    }

    function displayResults(score, total, results) {
      const form = document.getElementById('quiz-form');
      const resultsDiv = document.getElementById('results');
      const resultsDetails = document.getElementById('results-details');

      const percentage = Math.round((score / total) * 100);
      const resultsHtml = results
        .map((result, idx) => `
          <div class="result-item ${result.isCorrect ? 'correct' : 'incorrect'}">
            <div class="result-header">
              <span class="result-icon">${result.isCorrect ? '✓' : '✗'}</span>
              <strong>Question ${idx + 1}:</strong>
              <span>${result.question}</span>
            </div>
            <div class="result-details">
              <div>Your answer: ${result.selected.join(', ') || '(none selected)'}</div>
              <div>Correct answer: ${result.correct.join(', ')}</div>
            </div>
          </div>
        `)
        .join('');

      resultsDetails.innerHTML = `
        <div class="score-summary">
          <div class="score-display">${score}/${total}</div>
          <div class="score-percentage">${percentage}%</div>
        </div>
        ${resultsHtml}
      `;

      form.style.display = 'none';
      resultsDiv.style.display = 'block';
    }
  </script>
</body>
</html>
